<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="Compare Marginalia plans for personal notes and shared notebooks. Start free, or choose Pro or Team.">
  <title>Pricing — Marginalia</title>
  <style>
    :root {
      color-scheme: light;
      --canvas: #fafbfc;
      --surface: #ffffff;
      --ink: #202d3d;
      --muted: #5f6b79;
      --line: #dce1e7;
      --accent: #245bd9;
      --accent-hover: #1947b3;
      --on-dark: #ffffff;
      --dark-muted: #c0cbd9;
      --dark-line: #435063;
      --soft-blue: #eaf0fd;
      --focus: #245bd9;
      --font-body: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      --font-editorial: Georgia, "Times New Roman", serif;
      --text-small: .875rem;
      --text-body: 1rem;
      --text-large: 1.125rem;
      --text-title: 1.5rem;
      --text-section: 2rem;
      --text-price: 3.5rem;
      --text-display: clamp(2.5rem, 5vw, 4rem);
      --space-1: 4px;
      --space-2: 8px;
      --space-3: 12px;
      --space-4: 16px;
      --space-6: 24px;
      --space-8: 32px;
      --space-12: 48px;
      --space-16: 64px;
      --space-24: 96px;
      --radius: 8px;
      --container: 1120px;
    }
    * { box-sizing: border-box; }
    body { margin: 0; color: var(--ink); background: var(--canvas); font: var(--text-body)/1.5 var(--font-body); -webkit-font-smoothing: antialiased; }
    h1, h2, h3, p { margin: 0; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; cursor: pointer; }
    a, button, summary { -webkit-tap-highlight-color: transparent; }
    a:focus-visible, button:focus-visible, summary:focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
    .container { width: min(var(--container), calc(100% - var(--space-16))); margin-inline: auto; }
    .skip-link { position: absolute; top: -100px; left: var(--space-4); padding: var(--space-3) var(--space-4); background: var(--surface); z-index: 2; }
    .skip-link:focus { top: var(--space-4); }
    .site-header { background: var(--surface); border-bottom: 1px solid var(--line); }
    .nav { min-height: 88px; display: flex; align-items: center; justify-content: space-between; gap: var(--space-8); }
    .logo { display: inline-flex; align-items: center; gap: var(--space-3); font: 600 1.75rem/1 var(--font-editorial); letter-spacing: -.04em; white-space: nowrap; }
    .logo svg { width: 28px; height: 32px; color: var(--accent); flex-shrink: 0; }
    .nav-links { display: flex; align-items: center; gap: var(--space-8); font-size: var(--text-small); font-weight: 500; }
    .nav-links > a { display: inline-flex; align-items: center; min-height: 44px; color: var(--muted); }
    .nav-links > a:hover { color: var(--accent); }
    .nav-links > a[aria-current] { color: var(--ink); text-decoration: underline; text-underline-offset: 8px; text-decoration-color: var(--accent); text-decoration-thickness: 2px; }
    .nav-links .signup { padding: var(--space-3) var(--space-4); border: 1px solid var(--line); border-radius: var(--radius); color: var(--ink); }
    .nav-links .signup:hover { border-color: var(--ink); background: var(--canvas); }
    .hero { text-align: center; padding: var(--space-16) 0 var(--space-12); }
    .hero h1 { font: 400 var(--text-display)/1.12 var(--font-editorial); letter-spacing: -.045em; text-wrap: balance; }
    .hero p { margin: var(--space-4) auto 0; max-width: 52ch; color: var(--muted); font-size: var(--text-large); text-wrap: pretty; }
    .billing { display: inline-flex; align-items: center; gap: var(--space-1); margin-top: var(--space-8); padding: var(--space-1); border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
    .billing button { display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2); min-height: 44px; padding: var(--space-2) var(--space-4); border: 0; border-radius: var(--space-1); background: transparent; color: var(--muted); font-size: var(--text-small); }
    .billing button[aria-pressed="true"] { background: var(--ink); color: var(--on-dark); }
    .billing button:hover:not([aria-pressed="true"]) { background: var(--canvas); color: var(--ink); }
    .saving { color: var(--accent); background: var(--soft-blue); padding: 2px var(--space-2); border-radius: var(--space-1); font-size: .75rem; font-weight: 600; white-space: nowrap; }
    .plans { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-6); }
    .plan { padding: var(--space-8); background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); display: flex; flex-direction: column; }
    .plan-heading { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); }
    .plan h2 { font-size: var(--text-title); line-height: 1.3; letter-spacing: -.03em; font-weight: 600; }
    .desc { margin-top: var(--space-2); color: var(--muted); font-size: var(--text-small); }
    .price { display: flex; align-items: baseline; gap: var(--space-2); margin-top: var(--space-8); font-variant-numeric: tabular-nums; white-space: nowrap; }
    .amount { font-size: var(--text-price); font-weight: 500; letter-spacing: -.06em; line-height: 1.15; }
    .price-unit { color: var(--muted); font-size: var(--text-small); }
    .billing-note { margin-top: var(--space-2); color: var(--muted); font-size: var(--text-small); min-height: 21px; }
    .btn { display: flex; justify-content: center; align-items: center; gap: var(--space-2); min-height: 48px; padding: var(--space-3) var(--space-4); margin-top: var(--space-6); border: 1px solid var(--line); border-radius: var(--space-1); font-size: var(--text-small); font-weight: 600; transition: background 150ms ease-out, border-color 150ms ease-out; }
    .btn:hover { background: var(--canvas); border-color: var(--ink); }
    .btn:active, .billing button:active { transform: translateY(1px); }
    .plan ul { list-style: none; padding: var(--space-6) 0 0; margin: var(--space-6) 0 0; border-top: 1px solid var(--line); }
    .plan li { display: flex; align-items: baseline; gap: var(--space-3); padding-block: var(--space-2); font-size: var(--text-small); }
    .plan li::before { content: "✓"; color: var(--accent); font-weight: 600; flex: 0 0 16px; }
    .plan li.unavailable { color: var(--muted); }
    .plan li.unavailable::before { content: "−"; color: var(--muted); }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
    .plan.popular { background: var(--ink); color: var(--on-dark); border-color: var(--ink); }
    .popular .desc, .popular .price-unit, .popular .billing-note, .popular li.unavailable, .popular li.unavailable::before { color: var(--dark-muted); }
    .badge { color: var(--on-dark); border: 1px solid var(--dark-line); padding: var(--space-1) var(--space-2); border-radius: var(--space-1); font-size: .75rem; white-space: nowrap; }
    .popular .btn { border-color: var(--accent); background: var(--accent); color: var(--on-dark); }
    .popular .btn:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
    .popular ul { border-color: var(--dark-line); }
    .popular li::before { color: var(--on-dark); }
    .popular a:focus-visible { outline-color: var(--on-dark); }
    .features { margin-top: var(--space-16); padding-block: var(--space-12); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
    .features h2 { font-size: var(--text-small); font-weight: 500; color: var(--muted); margin-bottom: var(--space-8); }
    .feature-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-12); }
    .feature svg { width: 24px; height: 24px; stroke: var(--ink); fill: none; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; margin-bottom: var(--space-4); }
    .feature h3 { font-size: var(--text-body); font-weight: 600; margin-bottom: var(--space-2); }
    .feature p { font-size: var(--text-small); color: var(--muted); max-width: 32ch; }
    .faq { display: grid; grid-template-columns: 1fr 2fr; gap: var(--space-16); padding-block: var(--space-16) var(--space-24); }
    .faq h2 { font: 400 var(--text-section)/1.2 var(--font-editorial); letter-spacing: -.03em; text-wrap: balance; }
    .questions details { border-bottom: 1px solid var(--line); }
    .questions details:first-child { border-top: 1px solid var(--line); }
    summary { list-style: none; display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); min-height: 64px; padding-block: var(--space-4); font-size: var(--text-body); font-weight: 500; cursor: pointer; }
    summary::-webkit-details-marker { display: none; }
    summary::after { content: "+"; color: var(--muted); font-size: var(--text-title); font-weight: 400; }
    details[open] summary::after { content: "−"; }
    summary:hover { color: var(--accent); }
    details p { max-width: 65ch; padding: 0 var(--space-8) var(--space-6) 0; font-size: var(--text-small); color: var(--muted); }
    .footer { border-top: 1px solid var(--line); background: var(--surface); }
    .footer-inner { display: flex; justify-content: space-between; align-items: center; gap: var(--space-6); padding-block: var(--space-8); }
    .footer .logo { font-size: 1.25rem; }
    .footer p { color: var(--muted); font-size: .75rem; }
    @media (max-width: 1000px) {
      .nav-links { gap: var(--space-6); }
      .plans { gap: var(--space-4); }
      .plan { padding: var(--space-6); }
      .plan-heading { align-items: flex-start; flex-direction: column; min-height: 64px; }
      .feature-grid { gap: var(--space-6); }
      .faq { gap: var(--space-8); }
    }
    @media (max-width: 760px) {
      .container { width: calc(100% - var(--space-12)); }
      .nav { padding-block: var(--space-4); flex-wrap: wrap; gap: var(--space-4); min-height: auto; }
      .nav-links { flex-wrap: wrap; gap: var(--space-4); width: 100%; justify-content: space-between; }
      .hero { padding-top: var(--space-12); padding-bottom: var(--space-8); }
      .hero p { font-size: var(--text-body); max-width: 36ch; }
      .plans { grid-template-columns: 1fr; gap: var(--space-6); }
      .plan { padding: var(--space-8); }
      .plan-heading { min-height: 0; flex-direction: row; align-items: center; }
      .price { margin-top: var(--space-6); }
      .feature-grid { grid-template-columns: 1fr; gap: var(--space-8); }
      .feature p { max-width: 50ch; }
      .features { margin-top: var(--space-12); padding-block: var(--space-8); }
      .faq { grid-template-columns: 1fr; gap: var(--space-8); padding-block: var(--space-12) var(--space-16); }
      .footer-inner { align-items: flex-start; flex-direction: column; gap: var(--space-3); }
    }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="site-header">
    <nav class="nav container" aria-label="Main navigation">
      <a class="logo" href="#" aria-label="Marginalia home">
        <svg viewBox="0 0 28 32" fill="none" aria-hidden="true"><path d="M5 3h18v26H5z" stroke="currentColor" stroke-width="1.5"/><path d="M10 3v26M14 11h5M14 16h5M14 21h3" stroke="currentColor" stroke-width="1.5"/></svg>
        Marginalia
      </a>
      <div class="nav-links">
        <a href="#features">Features</a>
        <a href="#plans" aria-current="page">Pricing</a>
        <a href="#">Blog</a>
        <a href="#">Log in</a>
        <a class="signup" href="#">Sign up free <span aria-hidden="true">&nbsp;↗</span></a>
      </div>
    </nav>
  </header>

  <main id="main" class="container">
    <section class="hero" aria-labelledby="page-title">
      <h1 id="page-title">Plans for every notebook.</h1>
      <p>From your first note to your team’s shared workspace.<br>Choose the plan that fits the way you work.</p>
      <div class="billing" role="group" aria-label="Billing period">
        <button type="button" data-period="monthly" aria-pressed="true">Monthly</button>
        <button type="button" data-period="yearly" aria-pressed="false">Yearly <span class="saving">Save 20%</span></button>
      </div>
    </section>

    <section class="plans" id="plans" aria-label="Compare pricing plans">
      <article class="plan">
        <div class="plan-heading"><h2>Starter</h2></div>
        <p class="desc">For your everyday notes.</p>
        <div class="price"><span class="amount">$0</span><span class="price-unit">/ month</span></div>
        <p class="billing-note">Free plan</p>
        <a class="btn" href="#" aria-label="Choose the Starter plan">Choose Starter</a>
        <ul>
          <li>Up to 100 notes</li>
          <li>2 devices</li>
          <li>Basic search</li>
          <li class="unavailable"><span>Offline access<span class="sr-only"> — not included</span></span></li>
          <li class="unavailable"><span>Shared notebooks<span class="sr-only"> — not included</span></span></li>
        </ul>
      </article>

      <article class="plan popular">
        <div class="plan-heading"><h2>Pro</h2><span class="badge">Most popular</span></div>
        <p class="desc">More room for your ideas.</p>
        <div class="price"><span class="amount" id="pro-price">$8</span><span class="price-unit">/ month</span></div>
        <p class="billing-note" id="pro-billing">Billed monthly</p>
        <a class="btn" href="#" aria-label="Start your free Pro trial">Try Pro free <span aria-hidden="true">→</span></a>
        <ul>
          <li>Unlimited notes</li>
          <li>Unlimited devices</li>
          <li>Full-text search inside PDFs</li>
          <li>Offline access</li>
          <li class="unavailable"><span>Shared notebooks<span class="sr-only"> — not included</span></span></li>
        </ul>
      </article>

      <article class="plan">
        <div class="plan-heading"><h2>Team</h2></div>
        <p class="desc">A shared space to work together.</p>
        <div class="price"><span class="amount" id="team-price">$14</span><span class="price-unit">/ user / month</span></div>
        <p class="billing-note" id="team-billing">Billed monthly</p>
        <a class="btn" href="#" aria-label="Choose the Team plan">Choose Team</a>
        <ul>
          <li>Everything in Pro</li>
          <li>Shared notebooks</li>
          <li>Admin controls</li>
          <li>Priority support</li>
          <li>Single sign-on (SSO)</li>
        </ul>
      </article>
    </section>
    <p class="sr-only" id="billing-status" role="status"></p>

    <section class="features" id="features" aria-labelledby="features-heading">
      <h2 id="features-heading">The essentials, thoughtfully covered.</h2>
      <div class="feature-grid">
        <div class="feature">
          <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5M7 8h6M7 11h4"/></svg>
          <h3>Find what you need</h3>
          <p>Fast search brings your notes back into focus.</p>
        </div>
        <div class="feature">
          <svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/></svg>
          <h3>Keep your notes secure</h3>
          <p>Your notes are encrypted and kept safe.</p>
        </div>
        <div class="feature">
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7a8 8 0 0 0-14-2L3 8m0-5v5h5M4 17a8 8 0 0 0 14 2l3-3m0 5v-5h-5"/></svg>
          <h3>Pick up where you left off</h3>
          <p>Keep your notes in sync across your devices.</p>
        </div>
      </div>
    </section>

    <section class="faq" aria-labelledby="faq-heading">
      <h2 id="faq-heading">A few things<br>you might be wondering.</h2>
      <div class="questions">
        <details open>
          <summary>Can I cancel anytime?</summary>
          <p>Yes. You can cancel your subscription at any time, no questions asked.</p>
        </details>
        <details>
          <summary>Is there a free trial for Pro?</summary>
          <p>Yes. Pro comes with a 14-day free trial. No credit card required.</p>
        </details>
        <details>
          <summary>Do you offer student discounts?</summary>
          <p>Students get 50% off Pro with a valid school email.</p>
        </details>
      </div>
    </section>
  </main>

  <footer class="footer">
    <div class="footer-inner container">
      <a class="logo" href="#">Marginalia</a>
      <p>© 2026 Marginalia Inc. All rights reserved.</p>
    </div>
  </footer>
  <script>
    const billingButtons = document.querySelectorAll('"'[data-period]');
    billingButtons.forEach(button => {
      button.addEventListener('click', () => {
        const yearly = button.dataset.period === 'yearly';
        billingButtons.forEach(option => option.setAttribute('aria-pressed', String(option === button)));
        document.getElementById('pro-price').textContent = yearly ? '"'$6.40'"' : '"'$8'"';
        document.getElementById('team-price').textContent = yearly ? '"'$11.20'"' : '"'$14'"';
        document.getElementById('pro-billing').textContent = yearly ? '"'$76.80 billed yearly'"' : 'Billed monthly';
        document.getElementById('team-billing').textContent = yearly ? '"'$134.40 per user, billed yearly'"' : 'Billed monthly';
        document.getElementById('billing-status').textContent = yearly
          ? 'Yearly billing selected. Pro: "'$6.40 per month, $76.80 billed yearly. Team: $11.20 per user per month, $134.40 per user billed yearly.'"'
          : 'Monthly billing selected. Pro: "'$8 per month. Team: $14 per user per month.'"';
      });
    });
  </script>
</body>
</html>
EOF"

